using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.JournalEntries.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.JournalEntries.Commands.CreateJournalEntry;public sealed class CreateJournalEntryCommandHandler(IJournalEntryRepository repository,IApplicationDbContext db):IRequestHandler<CreateJournalEntryCommand,Result<JournalEntryDto>>{public async Task<Result<JournalEntryDto>>Handle(CreateJournalEntryCommand request,CancellationToken cancellationToken){if(await repository.ExistsByNumberAsync(request.EntryNumber,cancellationToken))return Result.Failure<JournalEntryDto>(JournalEntryErrors.Duplicate);var e=JournalEntry.Create(request.EntryNumber,request.EntryDate,request.CreatedByUserId,request.Description,request.SourceType,request.SourceId);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(JournalEntryDto.FromEntity(e));}}
